import { useStore } from '~/app/store/store';
import { SuperAppEncData } from '~/entities/super-app/model/types';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { PinFailType, VerificationType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { PATHS } from '~/shared/routes/paths';

export const PwFailPage = () => {
  const { routerState: state } = useGetRouterState<SuperAppEncData>();
  const { navigate } = useNavigate();
  const { data: userRes } = useGetUserInfoQuery();
  const moveToMobileVerification = () => {
    if (state?.pinFailType === PinFailType.로그인실패) {
      navigate(PATHS.mobileVerification, {
        replace: true,
        state: { ...state, verificationType: VerificationType.FailSetUser },
      });
    } else {
      navigate(PATHS.mobileVerification, {
        replace: true,
        state: { ...userRes.tbCstmrMastr, verificationType: VerificationType.ReSetUser },
      });
    }
  };
  const moveToFirst = () => {
    if (state?.pinFailType === PinFailType.로그인실패) {
      navigate(PATHS.root, { replace: true, state: { ...useStore.getState().superAppSlice.decData } });
    } else {
      navigate(PATHS.home, { replace: true });
    }
  };

  return (
    <div className="start login">
      <div className="content">
        <div className="sub-desc">
          <h3
            dangerouslySetInnerHTML={{
              __html: i18n.t('validation:pinAuthFailMessage'),
            }}
          ></h3>
        </div>
      </div>
      <div className="start-btn">
        <button type="button" onClick={() => moveToMobileVerification()}>
          {i18n.t('resetPinNumber')}
        </button>
        <button type="button" className="text-btn" onClick={() => moveToFirst()}>
          {i18n.t('navigateToStart')}
        </button>
      </div>
    </div>
  );
};
